window.CITOYEN = {source:'https://www.immigration.interieur.gouv.fr/sites/dgef/files/medias/documents/2026-07/LIVRET%20DU%20CITOYEN%202026_0.pdf',themes:[{id:'valeurs',name:'Les valeurs qui nous rassemblent',short:'Valeurs & symboles',color:'blue',icon:'✳',description:'Liberté, égalité, fraternité… et ce que cela change au quotidien.',pages:'6–14'},{id:'institutions',name:'Qui décide de quoi ?',short:'Institutions & Europe',color:'lime',icon:'▥',description:'De votre mairie au Parlement européen : trouvez vos repères.',pages:'16–23'},{id:'droits',name:'Vivre libres, vivre ensemble',short:'Droits & devoirs',color:'pink',icon:'⚖',description:'Des libertés fondamentales aux responsabilités de chacun.',pages:'25–36'},{id:'histoire',name:'Une histoire à explorer',short:'Histoire & culture',color:'orange',icon:'↔',description:'Les dates, les lieux et les personnes qui ont façonné la France.',pages:'38–60'},{id:'societe',name:'La France au quotidien',short:'Vie en société',color:'purple',icon:'⌂',description:'Santé, travail, école, famille : les essentiels de la vie en France.',pages:'62–76'}],lessons:[{id:'devise',theme:'valeurs',title:'Trois mots, une République',page:6,minutes:3,tag:'LA DEVISE',summary:'Liberté, égalité, fraternité : trois principes pour vivre ensemble.',facts:['La liberté permet de faire ses propres choix, dans le respect des droits des autres.','L’égalité signifie que la loi protège chacun de la même manière.','La fraternité invite à la solidarité entre les personnes.'],en:'Freedom, equality and fraternity are the Republic’s motto. Freedom comes with respect for other people’s rights.',prompt:'La liberté permet-elle de tout faire ?',answer:'Non. Elle s’exerce dans le respect de la loi et des droits d’autrui.',question:'Une personne exprime une opinion différente de la vôtre. Quel principe protège son droit de le faire, dans les limites de la loi ?',choices:['La liberté d’expression','L’obligation de voter','Le secret médical','La propriété privée'],correct:0,explanation:'La liberté d’expression protège aussi les opinions avec lesquelles on n’est pas d’accord. Les menaces et les incitations à la haine restent interdites.'}]};
// Original teaching text and exercises, based on the factual topics in the cited handbook pages.
function lesson(id,theme,title,page,summary,facts,en,prompt,answer,question,choices,correct,explanation){CITOYEN.lessons.push({id,theme,title,page,summary,facts,en,prompt,answer,question,choices,correct,explanation,minutes:3,tag:CITOYEN.themes.find(t=>t.id===theme).short.toUpperCase()})}
lesson('egalite','valeurs','Les mêmes droits pour chacun',6,'Une différence ne justifie pas une discrimination.',['La loi interdit les discriminations, notamment liées à l’origine, au sexe, au handicap ou à la religion.','Les femmes et les hommes ont les mêmes droits dans la vie professionnelle, familiale et publique.','Un recrutement doit reposer sur des critères professionnels pertinents.'],'Equal rights apply regardless of origin, gender, disability or religion. An employer must use relevant professional criteria.','Égalité signifie-t-elle que nous sommes tous identiques ?','Non : nous sommes différents, mais égaux en droits.','Un employeur écarte une candidate uniquement parce qu’elle est une femme. Comment qualifier cette décision ?',['Un choix toujours autorisé','Une discrimination interdite','Une règle de laïcité','Une obligation professionnelle'],1,'Le sexe ne peut pas justifier l’exclusion d’une candidate. L’égalité s’applique aussi au recrutement.');
lesson('fraternite','valeurs','La solidarité en action',7,'La fraternité devient concrète quand on s’entraide.',['La Sécurité sociale organise une solidarité collective.','Les cotisations contribuent notamment au financement des retraites et de la protection sociale.','Le bénévolat et les associations permettent de participer à la vie de son quartier.'],'Fraternity includes collective solidarity, social protection and helping others through community organisations.','Quel lien existe entre fraternité et Sécurité sociale ?','La protection sociale est une forme de solidarité collective.','Quel geste illustre le mieux la fraternité ?',['Refuser toute entraide','Imposer ses convictions','Participer à une collecte alimentaire','Écarter une personne en raison de son origine'],2,'Une collecte alimentaire est un exemple de solidarité. La fraternité dépasse les liens familiaux et les origines.');
lesson('symboles','valeurs','Reconnaître les symboles',8,'Drapeau, Marianne, coq : chaque symbole raconte quelque chose.',['Le drapeau français associe le bleu, le blanc et le rouge.','Marianne représente la République et porte un bonnet phrygien, symbole de liberté.','Le coq est un symbole national populaire, même s’il n’est pas un emblème défini par la Constitution.'],'Marianne represents the Republic. The tricolour is the national flag; the rooster is a widely recognised national symbol.','Que représente Marianne ?','La République française.','Quel accessoire est associé à Marianne ?',['Une couronne royale','Un casque de cycliste','Un chapeau haut-de-forme','Un bonnet phrygien'],3,'Le bonnet phrygien rappelle la liberté. Marianne est une représentation symbolique de la République.');
lesson('hymne','valeurs','Un hymne et une fête',8,'Deux repères à associer : La Marseillaise et le 14 juillet.',['Rouget de Lisle compose La Marseillaise en 1792.','Le 14 juillet renvoie à la prise de la Bastille en 1789 et à la Fête de la Fédération en 1790.','Le français est la langue de la République. Retrouvez les paroles de l’hymne à la page 9 du livret.'],'The national anthem is La Marseillaise, composed in 1792. The national holiday is 14 July.','Qui a composé La Marseillaise ?','Rouget de Lisle, en 1792.','Quel événement est associé au 14 juillet 1790 ?',['La Fête de la Fédération','La fin de la Première Guerre mondiale','La création de la Ve République','L’abolition de la peine de mort'],0,'1789 correspond à la prise de la Bastille ; 1790 à la Fête de la Fédération. Le 14 juillet commémore ces deux repères.');
lesson('republique','valeurs','Les quatre principes',10,'Indivisible, laïque, démocratique et sociale.',['La Constitution du 4 octobre 1958 organise les pouvoirs de la Ve République.','Indivisible : la souveraineté appartient à l’ensemble du peuple ; démocratique : le peuple exerce le pouvoir.','Laïque : liberté de conscience et neutralité de l’État ; sociale : solidarité et protection des personnes.'],'The Republic is indivisible, secular, democratic and social. These four principles are set out in Article 1 of the Constitution.','Que signifie le caractère « social » de la République ?','Elle organise la solidarité et favorise l’égalité des chances.','Quel texte organise les institutions de la Ve République ?',['Le règlement d’une entreprise','La Constitution de 1958','Un contrat de location','Le programme d’un parti'],1,'La Constitution fixe les règles fondamentales de l’État, organise les pouvoirs et protège les droits.');
lesson('laicite','valeurs','Croire, ne pas croire, changer',10,'La laïcité protège la liberté de conscience.',['Chacun peut avoir une religion, ne pas en avoir ou changer de conviction.','La loi de 1905 pose le principe de séparation des Églises et de l’État ; des régimes particuliers et exceptions existent.','La laïcité impose la neutralité de l’État, pas l’athéisme aux citoyens.'],'Secularism protects freedom of belief and non-belief. State neutrality does not require citizens to be atheists.','La laïcité interdit-elle les religions ?','Non. Elle garantit la liberté de conscience et la neutralité de l’État.','Une personne souhaite abandonner sa religion. Que garantit la République ?',['L’obligation d’obtenir un permis','L’accord obligatoire de son employeur','La liberté de changer de conviction','L’interdiction de changer'],2,'La liberté de conscience inclut le droit de croire, de ne pas croire et de changer de religion.');
lesson('neutralite','valeurs','La laïcité selon le lieu',12,'Agent public, usager, élève : les règles ne sont pas identiques.',['Les agents publics doivent rester neutres dans l’exercice de leurs fonctions.','Les usagers peuvent en principe porter un signe religieux, en respectant le fonctionnement du service.','À l’école publique, les élèves ne portent pas de signes religieux ostensibles. En entreprise privée, les restrictions doivent être justifiées et encadrées.'],'Public employees must be neutral at work. Public-service users generally retain freedom of religious expression. Public schools have specific rules.','Un usager de mairie doit-il respecter la même neutralité qu’un agent ?','Non. L’obligation de neutralité concerne l’agent dans ses fonctions.','Une agente de mairie utilise le guichet pour convaincre les usagers d’adopter sa religion. Est-ce autorisé ?',['Oui, si la file est courte','Oui, avec l’accord d’un collègue','Oui, si elle parle doucement','Non, elle doit respecter la neutralité du service'],3,'La neutralité garantit un traitement égal. Un agent ne doit pas utiliser ses fonctions pour faire du prosélytisme.');
lesson('pouvoirs','institutions','Trois pouvoirs, un équilibre',16,'Faire la loi, l’appliquer, rendre la justice.',['Le pouvoir législatif appartient au Parlement, qui vote les lois.','L’exécutif conduit la politique du pays et met les lois en œuvre.','L’autorité judiciaire rend la justice. La séparation des pouvoirs évite leur concentration.'],'The legislature makes laws, the executive implements policy, and the judiciary administers justice. Separation limits concentration of power.','Pourquoi séparer les pouvoirs ?','Pour limiter l’arbitraire et protéger les libertés.','Quelle mission correspond au pouvoir législatif ?',['Voter les lois','Soigner les patients','Délivrer les billets de train','Juger chaque infraction'],0,'Le Parlement exerce le pouvoir législatif. Le gouvernement conduit la politique de la Nation et la justice tranche les litiges.');
lesson('president','institutions','Président et Premier ministre',16,'Deux fonctions à distinguer.',['Le président de la République est le chef de l’État et des armées. Il est élu pour cinq ans au suffrage universel direct.','Il nomme le Premier ministre, qui dirige l’action du Gouvernement.','Le président nomme les autres membres du Gouvernement sur proposition du Premier ministre.'],'The President is head of state. The Prime Minister, appointed by the President, directs the government’s work.','Qui dirige l’action du Gouvernement ?','Le Premier ministre.','Qui nomme le Premier ministre ?',['Le maire de Paris','Le président de la République','Les préfets','La Banque centrale européenne'],1,'Le président nomme le Premier ministre. Ne confondez pas le chef de l’État et le chef du Gouvernement.');
lesson('parlement','institutions','Deux chambres pour le Parlement',16,'L’Assemblée nationale et le Sénat forment le Parlement.',['Les 577 députés sont élus au suffrage direct, normalement pour cinq ans. Une dissolution peut provoquer des élections anticipées.','Les 348 sénateurs sont élus au suffrage indirect pour six ans.','Le Parlement vote les lois et contrôle l’action du Gouvernement.'],'Parliament has two chambers: the National Assembly and the Senate. MPs are directly elected; senators are indirectly elected.','Combien de députés siègent à l’Assemblée nationale ?','577 députés.','Quel ensemble forme le Parlement français ?',['Le président et les préfets','Les maires et les ministres','L’Assemblée nationale et le Sénat','La Cour de cassation et le Conseil d’État'],2,'Le Parlement comprend deux chambres. Le Gouvernement est une institution distincte.');
lesson('vote','institutions','Voter : un droit personnel',17,'Un vote est libre, personnel et secret.',['Pour voter à l’élection présidentielle, il faut notamment être français, majeur, inscrit et jouir de ses droits civiques.','Les citoyens de l’Union européenne résidant en France peuvent voter aux élections municipales et européennes, sous conditions.','Voter est un devoir civique, mais n’est pas une obligation légale pour les électeurs ordinaires.'],'Presidential voting requires French citizenship. EU citizens living in France can vote in municipal and European elections under the applicable conditions.','Le vote est-il obligatoire en France ?','Non. C’est un droit et un devoir civique, sans obligation légale générale.','Quel principe protège le choix personnel de l’électeur ?',['La publication obligatoire de son bulletin','L’accord de son employeur','Le vote collectif dans l’isoloir','Le secret du vote'],3,'Le secret du vote permet de choisir sans pression. L’isoloir protège ce choix.');
lesson('territoires','institutions','Commune, département, région',19,'Associer un territoire à ses missions aide à mémoriser.',['La commune gère notamment les écoles maternelles et élémentaires et l’état civil. Le conseil municipal élit le maire.','Le département s’occupe notamment des collèges et de l’action sociale.','La région intervient notamment pour les lycées, les transports régionaux et le développement économique. Le préfet représente l’État.'],'Remember the school ladder: commune = primary school; département = collège; région = lycée. The prefect represents the central state.','Qui gère les collèges publics ?','Le département.','À quelle collectivité associer la construction et l’entretien des lycées publics ?',['La région','La commune seule','Le Parlement européen','La CPAM'],0,'Maternelle et élémentaire : commune. Collège : département. Lycée : région.');
lesson('outremer','institutions','La France au-delà de l’Hexagone',20,'La République comprend la métropole et des territoires ultramarins.',['Le livret compte 18 régions : 13 en métropole et 5 en outre-mer.','Les cinq départements d’outre-mer sont la Guadeloupe, la Martinique, la Guyane, La Réunion et Mayotte.','D’autres territoires, comme la Polynésie française et la Nouvelle-Calédonie, ont des statuts particuliers.'],'France includes mainland Europe and overseas territories. Guadeloupe, Martinique, French Guiana, Réunion and Mayotte are overseas departments.','Quel département français se trouve en Amérique du Sud ?','La Guyane.','Lequel de ces territoires est un département français ?',['La Sicile','Madère','La Réunion','La Sardaigne'],2,'La Réunion est un département français dans l’océan Indien. L’outre-mer fait partie de la République.');
lesson('europe','institutions','Construire l’Europe',22,'L’idée de départ : rendre la paix durable.',['Six pays sont à l’origine de la CEE : France, Allemagne, Italie, Belgique, Pays-Bas et Luxembourg.','La CECA naît en 1951 ; le traité de Rome est signé en 1957 ; le traité de Maastricht en 1992.','Le Royaume-Uni quitte l’Union européenne en 2020. Le livret de 2026 présente une Union de 27 États membres.'],'European integration grew after World War II. Remember 1951 (ECSC), 1957 (Rome), 1992 (Maastricht) and 2020 (Brexit).','Quel traité a été signé en 1992 ?','Le traité de Maastricht, à l’origine de l’Union européenne.','Quel pays a quitté l’Union européenne en 2020 ?',['La Belgique','Le Royaume-Uni','L’Italie','Le Luxembourg'],1,'Le Brexit désigne la sortie du Royaume-Uni de l’Union européenne.');
lesson('ue-symboles','institutions','Les repères européens',23,'Des lieux, une monnaie et des symboles communs.',['Le Parlement européen siège à Strasbourg ; la Commission européenne est à Bruxelles ; la BCE est à Francfort.','Le drapeau européen porte douze étoiles sur fond bleu. La Journée de l’Europe est le 9 mai.','L’hymne est l’Ode à la joie de Beethoven ; la devise est « Unie dans la diversité ». Les billets et pièces en euros circulent depuis 2002.'],'Strasbourg: European Parliament. Brussels: European Commission. Frankfurt: European Central Bank. Europe Day is 9 May.','Les douze étoiles représentent-elles le nombre actuel d’États membres ?','Non. Elles symbolisent notamment l’unité et l’harmonie.','Où siège la Commission européenne ?',['Paris','Lyon','Strasbourg','Bruxelles'],3,'La Commission est à Bruxelles. Le siège du Parlement européen est à Strasbourg.');
lesson('textes','droits','Les textes qui protègent',25,'Les droits fondamentaux sont garantis par plusieurs textes.',['La Déclaration des droits de l’homme et du citoyen date de 1789.','La Constitution, le préambule de 1946 et la Charte de l’environnement protègent aussi des droits fondamentaux.','La plupart des droits fondamentaux protègent les personnes quelle que soit leur nationalité. Certains droits politiques sont liés à la citoyenneté.'],'Fundamental rights protect people, not just citizens. Some political rights depend on citizenship.','À quelle année associer la DDHC ?','1789.','Une personne étrangère résidant en France est-elle protégée par des droits fondamentaux ?',['Oui, ces droits ne sont pas réservés aux seuls Français','Non, aucun droit ne la protège','Uniquement après dix ans','Seulement si elle peut voter'],0,'La dignité, la vie privée et l’accès à la justice protègent aussi les personnes étrangères.');
lesson('expression','droits','S’exprimer sans nuire',26,'La liberté d’expression s’applique aussi en ligne.',['Chacun peut exprimer ses idées, critiquer une institution ou une religion.','Les journalistes peuvent informer et critiquer le pouvoir.','L’incitation à la haine ou à la violence et la diffamation sont encadrées ou sanctionnées par la loi.'],'Free expression includes criticism of government and religion, but does not permit threats, incitement to hatred or unlawful defamation.','Peut-on critiquer une religion en France ?','Oui. Le blasphème n’est pas un délit ; les personnes restent protégées contre les infractions.','Sur un réseau social, une personne appelle à attaquer un groupe à cause de sa religion. Cet appel est-il protégé ?',['Oui, si le compte est privé','Non, la liberté d’expression ne couvre pas l’incitation à la violence','Oui, si elle utilise un pseudonyme','Oui, sans aucune limite'],1,'Les règles de protection des personnes s’appliquent aussi sur les réseaux sociaux.');
lesson('vie-privee','droits','La dignité et la vie privée',28,'Chaque personne mérite le respect.',['La dignité interdit de traiter une personne comme un objet ; la torture, l’esclavage et le travail forcé sont interdits.','La vie privée comprend l’intimité et la protection des données personnelles.','Les professionnels de santé sont tenus au secret médical, sous réserve des exceptions prévues par la loi.'],'Human dignity, privacy and medical confidentiality are protected. Legal exceptions to confidentiality are specific, not a general permission to disclose.','Le secret médical protège quoi ?','La confidentialité des informations de santé d’une personne.','Un médecin souhaite raconter le dossier d’un patient à un voisin par curiosité. Peut-il le faire ?',['Oui, si le voisin est discret','Oui, après la consultation','Non, le secret médical s’y oppose','Oui, pour toute personne majeure'],2,'La curiosité d’un voisin ne justifie pas de révéler des informations médicales confidentielles.');
lesson('corps','droits','Choisir pour son corps',29,'Le consentement et l’intégrité de la personne sont essentiels.',['Les violences sexuelles, mutilations et actes imposés contre l’intégrité du corps sont interdits.','La contraception est accessible, y compris aux mineurs, dans le cadre prévu par la loi.','La liberté de recourir à l’IVG est garantie par la Constitution depuis 2024. La loi encadre ses conditions.'],'Bodily autonomy and consent matter. Constitutional protection of abortion was introduced in 2024; medical conditions are governed by law.','Que signifie IVG ?','Interruption volontaire de grossesse.','Quelle liberté a été expressément garantie par la Constitution en 2024 ?',['La liberté de ne jamais déclarer ses revenus','La liberté de conduire sans permis','La liberté d’imposer un traitement à autrui','La liberté de recourir à l’IVG'],3,'La protection constitutionnelle de l’IVG est un repère récent concernant les droits des femmes.');
lesson('justice','droits','Une justice pour tous',29,'Accéder à un juge et pouvoir se défendre.',['Une privation de liberté doit avoir une base légale. La présomption d’innocence protège la personne mise en cause.','Chacun a droit à un procès équitable et peut être assisté par un avocat.','L’aide juridictionnelle facilite l’accès à la justice sous conditions ; le Défenseur des droits intervient notamment contre les discriminations.'],'Everyone has a right to fair legal proceedings. Legal aid can cover costs under eligibility conditions; the Defender of Rights tackles discrimination and other rights violations.','Que signifie la présomption d’innocence ?','Une personne est présumée innocente tant que sa culpabilité n’a pas été légalement établie.','Quelle aide peut contribuer aux frais d’avocat d’une personne ayant peu de ressources ?',['L’aide juridictionnelle','La carte électorale','Le titre de transport','Le livret de famille'],0,'L’aide juridictionnelle est une aide financière de l’État, accordée sous conditions.');
lesson('participation','droits','Agir ensemble',30,'Association, réunion et manifestation permettent de participer.',['La loi de 1901 est un repère majeur de la liberté d’association.','Les personnes peuvent se réunir pacifiquement et défendre une cause.','Les manifestations sur la voie publique font l’objet d’une déclaration préalable ; les restrictions pour protéger l’ordre public sont contrôlées par le juge.'],'Association, peaceful assembly and protest are ways to participate. Demonstrations on public roads are subject to prior declaration.','La liberté d’association permet quoi ?','Créer ou rejoindre une association, dans le respect des lois.','Des habitants veulent agir ensemble pour leur quartier. Quelle démarche illustre la liberté d’association ?',['Imposer leur groupe à tous les voisins','Créer une association respectant la loi','Interdire les opinions opposées','Refuser toute règle commune'],1,'Une association permet une action collective volontaire. Elle reste soumise aux lois.');
lesson('lois','droits','Les règles s’appliquent à tous',32,'L’État de droit protège et oblige chacun.',['L’État et ses représentants doivent eux aussi respecter le droit.','Les infractions se classent par gravité : contraventions, délits, crimes.','Les sanctions sont prévues par la loi et prononcées par les autorités compétentes. Les décisions peuvent être contestées par les voies de recours.'],'The rule of law binds public authorities too. Offences are classified from least to most serious: contraventions, délits, crimes.','Quelle catégorie d’infraction est la plus grave ?','Le crime.','Un ministre peut-il ignorer la loi parce qu’il appartient au Gouvernement ?',['Oui, pendant son mandat','Oui, pour toute décision personnelle','Non, il est lui aussi soumis au droit','Oui, sans contrôle'],2,'L’État de droit signifie que le pouvoir n’est pas au-dessus des règles.');
lesson('devoirs','droits','Contribuer et porter secours',34,'Des responsabilités rendent la vie collective possible.',['Les impôts et cotisations financent notamment les services publics et la protection sociale, selon les règles applicables.','Les citoyens français participent à la défense nationale ; le recensement citoyen commence à 16 ans. Une convocation comme juré ne s’ignore pas.','Il faut porter assistance à une personne en danger lorsque c’est possible sans risque pour soi ou autrui, notamment en appelant les secours.'],'Taxes fund shared services. French citizens have specific civic duties. Assistance can mean calling emergency services without putting yourself or others in danger.','Aider implique-t-il de se mettre soi-même en danger ?','Non. Il faut agir sans risque pour soi ou autrui, notamment en alertant les secours.','Vous voyez un accident grave et pouvez téléphoner sans danger. Quelle réaction est adaptée ?',['Partir sans rien faire','Filmer uniquement pour les réseaux sociaux','Attendre que tous les témoins partent','Alerter les secours et suivre leurs instructions'],3,'Appeler les secours est une manière concrète de remplir le devoir d’assistance.');
lesson('anciens','histoire','Des rois aux Lumières',39,'Quelques personnages permettent de situer les grandes périodes.',['Clovis appartient au début du Moyen Âge ; Jeanne d’Arc joue un rôle dans la guerre de Cent Ans.','Henri IV promulgue l’édit de Nantes en 1598 ; Louis XIV, le Roi-Soleil, est associé à Versailles.','Voltaire, Rousseau et Montesquieu défendent notamment la tolérance et critiquent l’arbitraire. Leurs idées nourrissent la Révolution.'],'Connect people to eras: Clovis and Joan of Arc to the Middle Ages; Louis XIV to absolute monarchy; Enlightenment thinkers to ideas of liberty.','Quel roi est surnommé le Roi-Soleil ?','Louis XIV.','Quel lieu est particulièrement associé à Louis XIV ?',['Versailles','Le Parlement européen','La tour Eiffel','Le musée d’Orsay en tant que musée'],0,'Versailles est un grand symbole du pouvoir royal de Louis XIV.');
lesson('revolution','histoire','1789 : le grand tournant',40,'La Révolution remet en cause la monarchie absolue.',['La prise de la Bastille a lieu le 14 juillet 1789.','La Déclaration des droits de l’homme et du citoyen est adoptée en août 1789.','La Première République est proclamée en 1792. Louis XVI est exécuté en 1793.'],'Remember the sequence: Revolution and Declaration in 1789, Republic in 1792, execution of Louis XVI in 1793.','1789 et 1792 : quelle différence ?','1789 : Révolution et DDHC. 1792 : Première République.','À quelle année associer la Première République ?',['1789','1792','1848','1958'],1,'La Révolution commence en 1789, mais la Première République date de 1792.');
lesson('empire','histoire','Napoléon et le XIXe siècle',41,'La France passe plusieurs fois de la République à l’Empire ou à la monarchie.',['Napoléon Bonaparte devient empereur en 1804. Le Code civil date aussi de 1804.','Après 1815 viennent la Restauration puis la monarchie de Juillet, jusqu’à la révolution de 1848.','Napoléon III dirige le Second Empire de 1852 à 1870. Il ne faut pas le confondre avec Napoléon Ier.'],'Napoleon I is linked to 1804 and the Civil Code. Napoleon III is a different ruler, associated with the Second Empire.','À quel dirigeant associer le Code civil de 1804 ?','Napoléon Bonaparte.','Napoléon III dirige…',['La Ve République','La Première République','Le Second Empire','Le régime de Vichy'],2,'Le Second Empire va de 1852 à 1870. Le Premier Empire est celui de Napoléon Ier.');
lesson('abolition','histoire','1848 : l’abolition définitive',42,'Comprendre cette date, c’est aussi comprendre un devoir de mémoire.',['L’esclavage est définitivement aboli dans les colonies françaises en 1848. Victor Schœlcher participe à cette abolition.','La traite et l’esclavage ont causé des déportations forcées et des violences massives. Nantes a été un grand port de la traite.','La loi Taubira de 2001 reconnaît la traite et l’esclavage comme crimes contre l’humanité.'],'Slavery was definitively abolished in French colonies in 1848. Remembering this history is part of civic knowledge.','Quelle date retenir pour l’abolition définitive de l’esclavage ?','1848.','Quel personnage est associé au décret d’abolition de 1848 ?',['Louis XIV','Georges Pompidou','Jules Ferry','Victor Schœlcher'],3,'Victor Schœlcher est un acteur majeur de l’abolition de 1848.');
lesson('ecole-republique','histoire','L’école et les grandes libertés',43,'La IIIe République inscrit durablement des libertés dans la loi.',['Les lois de Jules Ferry rendent l’école publique gratuite en 1881, puis l’instruction obligatoire et l’école laïque en 1882.','La liberté de la presse est associée à la loi de 1881 ; celle d’association à la loi de 1901.','La séparation des Églises et de l’État date de 1905.'],'Link the Third Republic to public schooling and major liberties: 1881, 1882, 1901 and 1905.','Quelle année retenir pour la séparation des Églises et de l’État ?','1905.','Quel personnage est associé aux lois scolaires de 1881 et 1882 ?',['Jules Ferry','Jean Moulin','Robert Badinter','Rouget de Lisle'],0,'Jules Ferry est associé à l’école publique gratuite, laïque et à l’instruction obligatoire.');
lesson('guerres','histoire','Deux guerres mondiales',43,'Deux périodes et deux commémorations à distinguer.',['La Première Guerre mondiale dure de 1914 à 1918. Le 11 novembre rappelle l’armistice de 1918.','La Seconde Guerre mondiale dure de 1939 à 1945. Le 8 mai commémore la victoire de 1945 en Europe.','La Shoah est le génocide des Juifs d’Europe perpétré par les nazis et leurs collaborateurs.'],'World War I: 1914–1918, commemorated on 11 November. World War II: 1939–1945; 8 May commemorates victory in Europe.','Que commémore le 11 novembre ?','L’armistice du 11 novembre 1918.','Quelle période correspond à la Seconde Guerre mondiale ?',['1914–1918','1939–1945','1789–1792','1954–1962'],1,'Ne confondez pas les deux guerres : 1914–1918 et 1939–1945.');
lesson('resistance','histoire','Résister et libérer',44,'Des choix décisifs pendant l’Occupation.',['Le régime de Vichy, dirigé par Pétain, collabore avec l’Allemagne nazie.','Charles de Gaulle lance son appel le 18 juin 1940. Jean Moulin participe à l’unification de la Résistance.','Le débarquement en Normandie a lieu le 6 juin 1944 ; Paris est libéré le 25 août 1944.'],'Vichy collaborated with Nazi Germany. De Gaulle’s appeal and Jean Moulin’s work are central Resistance landmarks.','Qui a contribué à unifier la Résistance intérieure ?','Jean Moulin.','À quelle date associer l’appel du général de Gaulle ?',['14 juillet 1789','11 novembre 1918','18 juin 1940','8 mai 1945'],2,'L’appel du 18 juin 1940 invite à poursuivre le combat.');
lesson('apres-guerre','histoire','Reconstruire après 1945',44,'La sortie de la guerre transforme la France et le monde.',['Les Françaises obtiennent le droit de vote en 1944 et votent pour la première fois en 1945.','La Sécurité sociale est créée en 1945 ; l’ONU est aussi fondée en 1945.','La IVe République commence en 1946. Après la guerre, les mouvements de décolonisation conduisent notamment à l’indépendance de l’Algérie en 1962.'],'Women gained voting rights in 1944 and first voted in 1945. Postwar landmarks include social security, the UN and decolonisation.','Droit de vote des femmes : 1944 ou 1945 ?','Droit accordé en 1944 ; premier vote en 1945.','Quelle organisation internationale est créée en 1945 pour contribuer à la paix ?',['La CECA','La CEE','La Banque de France','L’ONU'],3,'L’Organisation des Nations Unies est fondée après la Seconde Guerre mondiale.');
lesson('cinquieme','histoire','Depuis 1958 : la Ve République',45,'C’est le régime politique actuel de la France.',['La Constitution de la Ve République est promulguée le 4 octobre 1958. Charles de Gaulle en devient le premier président.','Mai 1968 est un important mouvement étudiant et social.','La majorité civile passe de 21 à 18 ans en 1974. En cas de vacance de la présidence, le président du Sénat assure normalement l’intérim.'],'The Fifth Republic began in 1958. Remember de Gaulle, May 1968 and the lowering of the age of majority to 18 in 1974.','Qui fut le premier président de la Ve République ?','Charles de Gaulle.','Quelle date correspond à la Constitution actuelle ?',['1958','1905','1792','1848'],0,'La Constitution du 4 octobre 1958 fonde la Ve République.');
lesson('droits-histoire','histoire','Des droits qui progressent',46,'Les droits actuels ont une histoire.',['Simone Veil défend la loi de 1975 sur l’IVG.','La peine de mort est abolie en 1981, sous François Mitterrand, avec Robert Badinter comme ministre de la Justice.','Le mariage est ouvert aux couples de même sexe en 2013.'],'Key rights milestones: abortion law in 1975, abolition of the death penalty in 1981, marriage equality in 2013.','Qui défend l’abolition de la peine de mort comme ministre de la Justice ?','Robert Badinter.','Sous quel président la peine de mort est-elle abolie ?',['Charles de Gaulle','François Mitterrand','Nicolas Sarkozy','Georges Pompidou'],1,'L’abolition a lieu en 1981, au début de la présidence de François Mitterrand.');
lesson('personnalites','histoire','Devenir français, contribuer',48,'Des parcours venus d’ailleurs participent à l’histoire commune.',['Marie Curie, née en Pologne, reçoit les prix Nobel de physique en 1903 et de chimie en 1911.','Joséphine Baker, née aux États-Unis, est artiste et résistante.','Marc Chagall est peintre ; Marguerite Yourcenar est écrivaine et la première femme élue à l’Académie française.'],'People born abroad have contributed to French science, art and public life. Curie, Baker, Chagall and Yourcenar are useful examples.','À quel domaine associer Marie Curie ?','La recherche scientifique, notamment la physique et la chimie.','Quel parcours correspond à Joséphine Baker ?',['Reine de France au XVIIe siècle','Fondatrice de la Banque centrale européenne','Artiste et résistante','Architecte de Versailles'],2,'Joséphine Baker a marqué la scène artistique et s’est engagée dans la Résistance.');
lesson('geographie','histoire','Situer la France',49,'Des frontières, des mers et des territoires variés.',['La France métropolitaine se situe en Europe occidentale. Elle a huit voisins terrestres, dont l’Allemagne, l’Espagne et l’Italie.','Elle est bordée par la Manche, la mer du Nord, l’océan Atlantique et la Méditerranée.','La Guyane a une frontière avec le Brésil ; La Réunion et Mayotte sont dans l’océan Indien.'],'Metropolitan France lies in western Europe. Overseas territories explain why France also has a land border with Brazil.','Quelle mer sépare la France de l’Angleterre ?','La Manche.','Quel pays a une frontière terrestre avec la Guyane française ?',['Le Canada','Le Japon','Le Portugal','Le Brésil'],3,'La Guyane se trouve en Amérique du Sud, à côté du Brésil et du Suriname.');
lesson('paysages','histoire','Fleuves, montagnes et patrimoine naturel',51,'Retenez un lieu par association.',['La Seine traverse Paris ; le Rhône traverse Lyon ; la Garonne traverse Toulouse et Bordeaux.','Les Alpes séparent notamment la France de l’Italie ; les Pyrénées séparent la France de l’Espagne.','Lascaux se trouve en Dordogne. Le Piton de la Fournaise se trouve à La Réunion.'],'Paris–Seine, Lyon–Rhône, Toulouse/Bordeaux–Garonne. Alps–Italy, Pyrenees–Spain. These pairs make geography easier to remember.','Quel fleuve traverse Paris ?','La Seine.','Quelle chaîne de montagnes sépare la France et l’Espagne ?',['Les Pyrénées','Les Vosges','Le Jura','Le Massif central'],0,'Les Pyrénées sont à la frontière franco-espagnole.');
lesson('monde','histoire','La France dans le monde',49,'Diplomatie, économie, langues et échanges.',['La France est membre permanent du Conseil de sécurité de l’ONU.','Kourou, en Guyane, accueille les lancements de fusées Ariane. L’aéronautique, l’agriculture et le luxe font partie des secteurs importants.','La francophonie rassemble les personnes qui parlent français à travers le monde.'],'France has a permanent seat on the UN Security Council. Francophonie refers to French-speaking people and communities across the world.','D’où décollent les fusées Ariane ?','De Kourou, en Guyane.','La francophonie désigne principalement…',['Les habitants de Paris uniquement','Les personnes et communautés qui parlent français','Les seuls citoyens nés en France','Un parti politique français'],1,'La langue française est partagée dans de nombreux pays, bien au-delà de la France.');
lesson('arts','histoire','Des œuvres et leurs auteurs',54,'Apprenez les noms par petites associations.',['La Joconde de Léonard de Vinci est exposée au Louvre. Le musée d’Orsay est associé aux impressionnistes.','Claude Monet peint Les Nymphéas ; Auguste Rodin sculpte Le Penseur ; Delacroix peint La Liberté guidant le peuple.','Molière écrit pour le théâtre, Victor Hugo écrit Les Misérables et Baudelaire Les Fleurs du Mal. George Sand, Simone de Beauvoir et Albert Camus sont des écrivains.'],'Learn pairs: Monet–Water Lilies; Rodin–The Thinker; Hugo–Les Misérables; Molière–theatre.','Dans quel musée peut-on voir La Joconde ?','Au musée du Louvre, à Paris.','Quel artiste est un sculpteur ?',['Claude Monet','Charles Baudelaire','Auguste Rodin','Claude Debussy'],2,'Rodin est sculpteur. Monet est peintre, Baudelaire poète et Debussy compositeur.');
lesson('culture','histoire','Les lieux et les traditions',56,'Le patrimoine se visite, s’écoute et se partage.',['La tour Eiffel est construite pour l’Exposition universelle de 1889. Le Mont-Saint-Michel est en Normandie ; le Palais des Papes est à Avignon.','La Fête de la musique a lieu le 21 juin ; les Journées du patrimoine, en septembre. Le 1er mai est la fête du Travail.','Le repas gastronomique des Français est un patrimoine culturel immatériel reconnu par l’UNESCO. Le Tour de France est une course cycliste créée en 1903.'],'Heritage includes buildings, music, traditions and shared meals. Eiffel Tower–1889; Music Day–21 June; Tour de France–cycling.','Dans quelle région se trouve le Mont-Saint-Michel ?','En Normandie.','Quel événement célèbre-t-on le 21 juin ?',['L’armistice de 1918','La fête nationale','La Journée de l’Europe','La Fête de la musique'],3,'La Fête de la musique a lieu chaque 21 juin depuis 1982.');
lesson('logement','societe','Louer et habiter',62,'Un logement implique des droits et des obligations.',['Le bail définit les conditions de location. Le locataire doit payer le loyer et les charges.','Le propriétaire doit fournir un logement décent. Les transformations importantes nécessitent son accord écrit.','Les logements sociaux sont accessibles sous conditions, notamment de ressources et de séjour. Les demandes se font par les canaux officiels.'],'A tenancy creates obligations for both landlord and tenant. Major alterations require permission; social housing has eligibility rules.','Peut-on modifier entièrement un logement loué sans accord ?','Non. Les transformations importantes nécessitent l’accord du propriétaire.','Un locataire veut abattre une cloison. Quelle démarche est adaptée ?',['Obtenir l’accord écrit du propriétaire avant les travaux','Commencer puis prévenir après','Ne jamais informer le propriétaire','Demander seulement à un voisin'],0,'Une transformation importante du logement ne se décide pas comme un simple aménagement décoratif.');
lesson('mobilite','societe','Se déplacer et être responsable',63,'La sécurité concerne tous les usagers de la route.',['Conduire exige les documents, le permis et l’assurance applicables au véhicule.','Une place réservée au handicap n’est pas une place libre pour tous.','La responsabilité civile concerne les dommages causés à autrui ; une assurance peut les couvrir selon le contrat.'],'Road rules protect everyone. Civil liability concerns harm caused to others; insurance coverage depends on the policy.','À quoi sert la responsabilité civile ?','À réparer les dommages causés à autrui.','Vous n’avez pas le droit d’utiliser une place réservée au handicap. Pouvez-vous y stationner quelques minutes ?',['Oui, si le moteur reste allumé','Non, la courte durée ne suffit pas à l’autoriser','Oui, les jours fériés','Oui, si le stationnement est gratuit'],1,'Les places réservées répondent à un besoin d’accessibilité. Leur usage est réglementé.');
lesson('environnement','societe','Des gestes pour le bien commun',65,'L’espace public et l’environnement sont l’affaire de chacun.',['Les déchets doivent suivre les consignes locales de tri ; les dépôts sauvages sont interdits.','Un appareil électroménager usagé peut être déposé dans une filière de collecte adaptée, notamment en déchèterie.','Respecter les règles sur le bruit, le tabac et les dégradations protège les autres. La vente d’alcool aux mineurs est interdite.'],'Use local waste rules and authorised collection points. Respect for shared spaces includes noise, smoking restrictions and avoiding damage.','Où déposer un appareil électroménager hors d’usage ?','Dans une filière adaptée, par exemple une déchèterie ou une reprise prévue par un vendeur.','Quel geste protège le mieux l’espace public ?',['Laisser son lave-linge sur le trottoir sans collecte prévue','Jeter ses mégots dans la rue','Utiliser la collecte adaptée pour les déchets encombrants','Déposer ses sacs dans un parc'],2,'Une déchèterie ou une collecte organisée évite les dépôts sauvages et permet le traitement adapté des déchets.');
lesson('sante','societe','Comprendre la protection sociale',68,'Carte Vitale, Assurance maladie, mutuelle : trois repères.',['La Sécurité sociale est fondée en 1945 sur la solidarité. L’Assurance maladie est l’une de ses branches.','La carte Vitale facilite la prise en charge et le remboursement ; elle ne garantit pas que tous les soins sont gratuits.','Une complémentaire santé peut couvrir une partie des frais restants. Le tiers payant évite d’avancer tout ou partie des frais concernés.'],'The Vitale card helps process health coverage. It does not mean every treatment is free. Supplementary insurance can cover some remaining costs.','Une carte Vitale signifie-t-elle que tous les soins sont gratuits ?','Non. La prise en charge dépend des soins et de la couverture.','À quoi sert principalement une mutuelle santé ?',['Remplacer les élections','Délivrer un titre de séjour','Fixer les lois','Compléter certains remboursements de santé'],3,'La complémentaire intervient selon les garanties du contrat, en complément de l’Assurance maladie.');
lesson('urgences','societe','Les numéros à connaître',69,'Associez chaque service à son numéro.',['15 : SAMU ; 17 : police-secours ; 18 : sapeurs-pompiers ; 112 : urgence européenne.','Le 114 est accessible notamment par SMS pour les personnes sourdes ou malentendantes.','119 : enfance en danger ; 115 : urgence sociale. Le 3919 informe et oriente sur les violences faites aux femmes ; ce n’est pas un numéro d’intervention d’urgence.'],'15 medical, 17 police, 18 firefighters, 112 European emergency. 3919 offers information and support; immediate danger requires emergency services.','Quel numéro permet de joindre le SAMU ?','Le 15.','Quel numéro d’urgence fonctionne à l’échelle européenne ?',['112','115','3919','3018'],0,'Le 112 oriente vers les services d’urgence. Tous les numéros d’aide ne déclenchent pas une intervention d’urgence.');
lesson('travail','societe','Les bases du droit du travail',70,'Les règles protègent salariés et employeurs.',['Le Code du travail, les conventions collectives et le règlement intérieur encadrent la vie professionnelle.','La durée légale du travail à temps complet est de 35 heures par semaine ; des heures supplémentaires et des régimes particuliers existent.','Le SMIC est le salaire minimum de croissance. Un litige individuel entre salarié du privé et employeur relève en principe des prud’hommes.'],'The standard legal full-time working week is 35 hours, not an absolute maximum. Employment disputes usually go to the labour court.','35 heures : durée légale ou plafond absolu ?','La durée légale du travail à temps complet, pas un plafond absolu.','Quelle juridiction traite normalement un litige individuel entre un salarié du privé et son employeur ?',['Le conseil municipal','Le conseil de prud’hommes','La Commission européenne','La CPAM'],1,'Les prud’hommes règlent les litiges individuels liés au contrat de travail dans le secteur privé.');
lesson('emploi','societe','Contrats, emploi et engagement',71,'Trouver sa place dans la vie professionnelle.',['Un CDI est à durée indéterminée ; un CDD est à durée déterminée. Le travail doit être déclaré.','France Travail accompagne la recherche d’emploi et verse des allocations lorsque les conditions sont remplies.','Les salariés peuvent adhérer à un syndicat. Créer une entreprise suppose de vérifier les règles de l’activité et, pour un étranger, les droits liés à son séjour.'],'CDI is open-ended; CDD is fixed-term. France Travail supports job seekers. A residence permit does not automatically authorise every type of self-employment.','Que signifie CDI ?','Contrat à durée indéterminée.','Quel organisme accompagne les demandeurs d’emploi ?',['Le musée du Louvre','Le Sénat','France Travail','Le bureau de vote'],2,'France Travail propose accompagnement, offres et formations ; les allocations dépendent de conditions précises.');
lesson('mariage','societe','Mariage et séparation',73,'Le consentement et l’égalité sont au cœur de la vie familiale.',['En France, c’est le mariage civil célébré en mairie qui produit les effets juridiques du mariage.','Le mariage est ouvert aux couples de même sexe depuis 2013. La polygamie est interdite.','Les époux peuvent divorcer. La séparation ne supprime pas automatiquement l’autorité parentale de l’un des parents.'],'Civil marriage is legally recognised. Same-sex couples can marry. Divorce does not automatically remove either parent’s parental authority.','Le mariage religieux seul suffit-il à se marier légalement en France ?','Non. Le mariage civil est nécessaire.','Après une séparation, qui exerce en principe l’autorité parentale ?',['Toujours le père seul','Toujours la mère seule','Toujours le maire','Les deux parents, sauf situation ou décision contraire'],3,'L’intérêt de l’enfant reste central. Une séparation ne fait pas disparaître automatiquement les responsabilités parentales.');
lesson('enfants','societe','Protéger les enfants',74,'L’autorité parentale est une responsabilité, pas un droit de violence.',['Les parents doivent protéger la sécurité, la santé, la vie privée et l’éducation de l’enfant.','L’autorité parentale s’exerce sans violences physiques ou psychologiques.','L’enfant doit être associé aux décisions qui le concernent selon son âge et sa maturité. Les parents doivent aussi accompagner les usages numériques.'],'Parental authority exists to protect the child. Physical and psychological violence are prohibited, and children should be heard according to age and maturity.','Peut-on utiliser la violence physique pour éduquer un enfant ?','Non. L’autorité parentale s’exerce sans violences.','Quel est l’objectif principal de l’autorité parentale ?',['Protéger l’intérêt et le développement de l’enfant','Imposer des violences éducatives','Supprimer toute vie privée de l’enfant','Dispenser l’enfant de toute instruction'],0,'L’autorité parentale réunit des droits et des devoirs pour protéger l’enfant.');
lesson('instruction','societe','Le parcours de l’école',75,'Maternelle, élémentaire, collège, lycée.',['L’instruction est obligatoire de 3 à 16 ans. L’instruction en famille exige une autorisation dans les cas prévus par la loi.','L’école publique est gratuite et laïque. La mairie intervient dans l’inscription à l’école primaire publique.','Les enfants allophones et les enfants en situation de handicap ont droit à l’éducation et à un accompagnement adapté.'],'Education is compulsory from ages 3 to 16. Public education is free and secular. Children learning French and children with disabilities have a right to education.','Après l’école élémentaire, quel établissement accueille les élèves ?','Le collège.','Entre quels âges l’instruction est-elle obligatoire ?',['De 6 à 14 ans','De 3 à 16 ans','De 10 à 18 ans','De 6 à 21 ans'],1,'Retenez 3–16 pour l’instruction obligatoire. Une obligation de formation concerne ensuite les 16–18 ans.');
